const input = $json.body ?? $json;
if (typeof input.campaignId !== 'string' || input.campaignId.trim() === '') throw new Error('campaignId is required');
return [{ json: { campaignId: input.campaignId.trim() } }];

const campaign = $('Store Campaign Lookup').item.json.data;
const spot = $('Load Spot - Spots').first().json;
const providers = $('Load Providers').all().map((item) => item.json);
const packages = $('Load Promotion Packages').all().map((item) => item.json);
const providerById = new Map(providers.map((provider) => [provider.id, provider]));
const slotStart = Date.parse(campaign.slotStartAt);
return packages.filter((pkg) => { const provider = providerById.get(pkg.providerId); return provider?.isActive !== false && Date.parse(pkg.validFrom) <= slotStart && Date.parse(pkg.validUntil) >= slotStart; }).map((pkg) => ({ json: { campaign, spot, provider: providerById.get(pkg.providerId), package: pkg, campaignContext: { campaignId: campaign.id, spotId: spot.id, spotName: spot.name, category: spot.category, city: spot.addressCity, region: spot.addressRegion, countryCode: spot.addressCountryCode, slotStartAt: campaign.slotStartAt, slotEndAt: campaign.slotEndAt, maximumBudgetPaise: campaign.maxBudgetPaise, maximumExpectedCpaPaise: campaign.maxExpectedCpaPaise } } }));

const source = $('Shortlist By Location And Availability').item.json;
const { campaign, spot, provider, package: pkg } = source;
const evidence = $json;
const now = Date.now();
const price = Number(evidence.verifiedPricePaise ?? pkg.pricePaise);
const minimumBookings = Number(evidence.historicalBookingMin);
const maximumBookings = Number(evidence.historicalBookingMax);
const deadline = evidence.verifiedPublicationDeadline ?? pkg.bookingDeadlineAt;
const available = provider.isActive !== false && Date.parse(pkg.validFrom) <= Date.parse(campaign.slotStartAt) && Date.parse(pkg.validUntil) >= Date.parse(campaign.slotStartAt);
const worstCpa = minimumBookings > 0 ? Math.floor((price - 1) / minimumBookings) + 1 : null;
const bestCpa = maximumBookings > 0 ? Math.floor((price - 1) / maximumBookings) + 1 : null;
const rejectionCodes = [];
const reject = (code) => { if (!rejectionCodes.includes(code)) rejectionCodes.push(code); };
if (!available) reject('PACKAGE_UNAVAILABLE');
if (price > Number(campaign.maxBudgetPaise)) reject('BUDGET_EXCEEDED');
if (pkg.hasRecurringBilling === true) reject('RECURRING_BILLING');
if (Date.parse(deadline) > Date.parse(campaign.slotStartAt) || now > Date.parse(deadline)) reject('PUBLICATION_DEADLINE_TOO_LATE');
if (minimumBookings <= 0) reject('ZERO_MINIMUM_EXPECTED_BOOKINGS');
if (worstCpa !== null && worstCpa > Number(campaign.maxExpectedCpaPaise)) reject('WORST_CASE_CPA_EXCEEDED');
if (evidence.verificationStatus === 'UNVERIFIED') reject('PROVIDER_EVIDENCE_UNVERIFIED');
if (Number(evidence.evidenceConfidence) < 0.8) reject('EVIDENCE_CONFIDENCE_TOO_LOW');
if (Number(evidence.localAudiencePercent) < 50) reject('AUDIENCE_GEOGRAPHY_MISMATCH');
if (evidence.verifiedPricePaise !== null && Number(evidence.verifiedPricePaise) !== Number(pkg.pricePaise)) reject('PRICE_CHANGED');
if (Number(pkg.discountBps) > Number(campaign.maxDiscountBps)) reject('DISCOUNT_EXCEEDED');
const clamp = (value) => Math.round(Math.min(100, Math.max(0, value)) * 100) / 100;
const geography = Number(evidence.localAudiencePercent) >= 50 ? 100 : 0;
const bookings = clamp((minimumBookings / Number(campaign.targetReservations)) * 100);
const confidence = clamp(Number(evidence.evidenceConfidence) * 100);
const cost = worstCpa === null ? 0 : clamp(((Number(campaign.maxExpectedCpaPaise) - worstCpa) / Number(campaign.maxExpectedCpaPaise)) * 100);
const windowMs = Date.parse(campaign.slotStartAt) - now;
const timing = !available || windowMs <= 0 || Date.parse(deadline) > Date.parse(campaign.slotStartAt) ? 0 : clamp(((Date.parse(campaign.slotStartAt) - Date.parse(deadline)) / windowMs) * 100);
const weightedFinalScore = rejectionCodes.length ? 0 : Math.round((geography * 0.30 + bookings * 0.25 + confidence * 0.20 + cost * 0.15 + timing * 0.10) * 100) / 100;
const reasons = rejectionCodes.map((code) => code.toLowerCase());
const sources = Array.isArray(evidence.sourceReferences) ? evidence.sourceReferences : [];
return [{ json: { eligible: rejectionCodes.length === 0, rejectionCodes, rejectionReasons: reasons, weightedFinalScore, scoreComponents: { geographicRelevance: geography, expectedBookingPotential: bookings, evidenceConfidence: confidence, costEfficiency: cost, timingAvailability: timing }, packageId: pkg.id, providerId: provider.id, providerName: provider.name, merchantId: pkg.merchantId, packageName: pkg.title, exactPricePaise: price, expectedBookingMin: minimumBookings, expectedBookingMax: maximumBookings, expectedCpaMinimumPaise: bestCpa, expectedCpaMaximumPaise: worstCpa, worstCaseExpectedCpaPaise: worstCpa, remainingBudgetPaise: Number(campaign.maxBudgetPaise) - price, evidenceConfidence: Number(evidence.evidenceConfidence), sources, deadline, discountBps: Number(pkg.discountBps), recurringBilling: pkg.hasRecurringBilling === true, campaign, spot, option: { id: 'option_' + campaign.id + '_' + pkg.id, campaignId: campaign.id, packageId: pkg.id, evidenceIds: sources.map((item) => item.id), score: Math.round(weightedFinalScore), totalCostPaise: price, expectedReservations: Number(pkg.expectedReservations), expectedCpaPaise: worstCpa ?? 0, discountBps: Number(pkg.discountBps), deterministicBudget: price <= Number(campaign.maxBudgetPaise), deterministicDeadline: Date.parse(deadline) <= Date.parse(campaign.slotStartAt) && now <= Date.parse(deadline), deterministicPrice: evidence.verifiedPricePaise === null || Number(evidence.verifiedPricePaise) === Number(pkg.pricePaise), deterministicMerchant: true, deterministicDiscount: Number(pkg.discountBps) <= Number(campaign.maxDiscountBps), deterministicCpa: worstCpa !== null && worstCpa <= Number(campaign.maxExpectedCpaPaise), passesDeterministicChecks: rejectionCodes.length === 0, rejectionReasons: reasons, generatedSummary: rejectionCodes.length === 0 ? 'Eligible deterministic option' : 'Rejected: ' + reasons.join(', '), createdAt: new Date().toISOString() } } }];

const options = $input.all().map((item) => item.json);
const eligible = options.filter((item) => item.eligible).sort((a,b) => b.weightedFinalScore - a.weightedFinalScore || (a.worstCaseExpectedCpaPaise ?? Number.MAX_SAFE_INTEGER) - (b.worstCaseExpectedCpaPaise ?? Number.MAX_SAFE_INTEGER) || Date.parse(a.deadline) - Date.parse(b.deadline) || a.packageId.localeCompare(b.packageId));
return [{ json: { options, selected: eligible[0] ?? null, rejectedAlternatives: options.filter((item) => !item.eligible).map((item) => ({ packageId: item.packageId, providerId: item.providerId, reasons: item.rejectionReasons })) } }];
